/*
 * Функция flang «Шаг разбора utf8».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param hod — «ход»: «Ход разбора utf8»
 * @param bayt — «байт»: число
 * @return значение: «Ход разбора utf8»
 */
fl_status tls_client_shag_razbora_utf8(fl_ctx *ctx, fl_value hod, fl_value bayt,
                                       fl_value *result, fl_error *error) {
  if (fl_variant_is(hod, "Разбираем utf8")) {
    fl_value tochki = fl_nothing();
    FL_TRY(fl_variant_field(ctx, hod, "точки", &tochki, error));
    fl_value kopilka = fl_nothing();
    FL_TRY(fl_variant_field(ctx, hod, "копилка", &kopilka, error));
    fl_value ostalos = fl_nothing();
    FL_TRY(fl_variant_field(ctx, hod, "осталось", &ostalos, error));
    fl_value nizhnyaya = fl_nothing();
    FL_TRY(fl_variant_field(ctx, hod, "нижняя", &nizhnyaya, error));
    fl_value verhnyaya = fl_nothing();
    FL_TRY(fl_variant_field(ctx, hod, "верхняя", &verhnyaya, error));
    fl_value zamescheniy = fl_nothing();
    FL_TRY(fl_variant_field(ctx, hod, "замещений", &zamescheniy, error));
    bool fl_t94 = false;
    FL_TRY(fl_cond(ctx, fl_flag(fl_equal(ostalos, fl_number(0.0))), &fl_t94,
                   error));
    if (fl_t94) {
      return tls_client_nachat_bayt(ctx, tochki, zamescheniy, bayt, result,
                                    error);
    } else {
      if (bayt.tag != FL_NUMBER || nizhnyaya.tag != FL_NUMBER)
        FL_TRY(fl_not_order(ctx, bayt, nizhnyaya, error));
      bool fl_t95 = false;
      FL_TRY(fl_cond(ctx, fl_flag(bayt.as.number >= nizhnyaya.as.number),
                     &fl_t95, error));
      fl_value fl_t96;
      if (fl_t95) {
        if (bayt.tag != FL_NUMBER || verhnyaya.tag != FL_NUMBER)
          FL_TRY(fl_not_order(ctx, bayt, verhnyaya, error));
        fl_t96 = fl_flag(bayt.as.number <= verhnyaya.as.number);
      } else {
        fl_t96 = fl_flag(false);
      }
      bool fl_t97 = false;
      FL_TRY(fl_cond(ctx, fl_t96, &fl_t97, error));
      if (fl_t97) {
        bool fl_t98 = false;
        FL_TRY(fl_cond(ctx, fl_flag(fl_equal(ostalos, fl_number(1.0))), &fl_t98,
                       error));
        if (fl_t98) {
          if (kopilka.tag != FL_NUMBER)
            FL_TRY(fl_not_numbers(ctx, "mul", kopilka, fl_number(64.0), error));
          if (bayt.tag != FL_NUMBER)
            FL_TRY(fl_not_numbers(ctx, "sub", bayt, fl_number(128.0), error));
          fl_value fl_t99 = fl_nothing();
          FL_TRY(fl_b_dobavit(
              ctx,
              fl_number((kopilka.as.number * 64.0) + (bayt.as.number - 128.0)),
              tochki, &fl_t99, error));
          fl_value fl_t101[6];
          fl_t101[0] = fl_t99;
          fl_t101[1] = fl_number(0.0);
          fl_t101[2] = fl_number(0.0);
          fl_t101[3] = fl_number(128.0);
          fl_t101[4] = fl_number(191.0);
          fl_t101[5] = zamescheniy;
          fl_value fl_t100 = fl_nothing();
          FL_TRY(fl_variant_new(ctx, "Разбираем utf8", tls_client_names_23,
                                fl_t101, 6, &fl_t100, error));
          *result = fl_t100;
          return FL_OK;
        } else {
          if (kopilka.tag != FL_NUMBER)
            FL_TRY(fl_not_numbers(ctx, "mul", kopilka, fl_number(64.0), error));
          if (bayt.tag != FL_NUMBER)
            FL_TRY(fl_not_numbers(ctx, "sub", bayt, fl_number(128.0), error));
          if (ostalos.tag != FL_NUMBER)
            FL_TRY(fl_not_numbers(ctx, "sub", ostalos, fl_number(1.0), error));
          fl_value fl_t103[6];
          fl_t103[0] = tochki;
          fl_t103[1] = fl_number((kopilka.as.number * 64.0) + (bayt.as.number - 128.0));
          fl_t103[2] = fl_number(ostalos.as.number - 1.0);
          fl_t103[3] = fl_number(128.0);
          fl_t103[4] = fl_number(191.0);
          fl_t103[5] = zamescheniy;
          fl_value fl_t102 = fl_nothing();
          FL_TRY(fl_variant_new(ctx, "Разбираем utf8", tls_client_names_23,
                                fl_t103, 6, &fl_t102, error));
          *result = fl_t102;
          return FL_OK;
        }
      } else {
        fl_value fl_t104 = fl_nothing();
        FL_TRY(fl_b_dobavit(ctx, fl_number(65533.0), tochki, &fl_t104, error));
        if (zamescheniy.tag != FL_NUMBER)
          FL_TRY(
              fl_not_numbers(ctx, "add", zamescheniy, fl_number(1.0), error));
        return tls_client_nachat_bayt(ctx, fl_t104,
                                      fl_number(zamescheniy.as.number + 1.0),
                                      bayt, result, error);
      }
    }
  } else {
    return fl_match_fail(ctx, hod, error);
  }
}

