/* Тело «Повторить»; глубину считает обёртка ниже. */
static fl_status tls_client_povtorit_body(fl_ctx *ctx, fl_value tekst,
                                          fl_value raz, fl_value *result,
                                          fl_error *error) {
  if (raz.tag != FL_NUMBER)
    FL_TRY(fl_not_order(ctx, raz, fl_number(0.0), error));
  bool fl_t537 = false;
  FL_TRY(fl_cond(ctx, fl_flag(raz.as.number <= 0.0), &fl_t537, error));
  if (fl_t537) {
    *result = tls_client_text_66;
    return FL_OK;
  } else {
    if (raz.tag != FL_NUMBER)
      FL_TRY(fl_not_numbers(ctx, "sub", raz, fl_number(1.0), error));
    const fl_value shag = fl_number(raz.as.number - 1.0);
    fl_value fl_t538 = fl_nothing();
    FL_TRY(fl_lt(ctx, shag, raz, &fl_t538, error));
    bool fl_t539 = false;
    FL_TRY(fl_cond(ctx, fl_t538, &fl_t539, error));
    fl_value fl_t540;
    if (fl_t539) {
      fl_t540 = shag;
    } else {
      fl_value fl_t541 = fl_nothing();
      FL_TRY(tls_client_mera_ubyvaet(ctx, shag, raz, &fl_t541, error));
      fl_t540 = fl_t541;
    }
    fl_value fl_t542 = fl_nothing();
    FL_TRY(tls_client_povtorit(ctx, tekst, fl_t540, &fl_t542, error));
    fl_value fl_t543 = fl_nothing();
    FL_TRY(fl_concat(ctx, tekst, fl_t542, &fl_t543, error));
    *result = fl_t543;
    return FL_OK;
  }
}

/*
 * Функция flang «Повторить».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param tekst — «текст»: строка
 * @param raz — «раз»: число
 * @return значение: строка
 */
fl_status tls_client_povtorit(fl_ctx *ctx, fl_value tekst, fl_value raz,
                              fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Повторить", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status =
        tls_client_povtorit_body(ctx, tekst, raz, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

