/* Тело «Байты до места»; глубину считает обёртка ниже. */
static fl_status tls_client_bayty_do_mesta_body(fl_ctx *ctx, fl_value tekst,
                                                fl_value mesto,
                                                fl_value *result,
                                                fl_error *error) {
  if (mesto.tag != FL_NUMBER)
    FL_TRY(fl_not_order(ctx, mesto, fl_number(0.0), error));
  bool fl_t1615 = false;
  FL_TRY(fl_cond(ctx, fl_flag(mesto.as.number <= 0.0), &fl_t1615, error));
  if (fl_t1615) {
    *result = fl_list(NULL, 0);
    return FL_OK;
  } else {
    fl_value fl_t1616 = fl_nothing();
    FL_TRY(tls_client_bayt_po_schyotu(ctx, tekst, mesto, &fl_t1616, error));
    if (mesto.tag != FL_NUMBER)
      FL_TRY(fl_not_numbers(ctx, "sub", mesto, fl_number(1.0), error));
    const fl_value shag = fl_number(mesto.as.number - 1.0);
    fl_value fl_t1617 = fl_nothing();
    FL_TRY(fl_lt(ctx, shag, mesto, &fl_t1617, error));
    bool fl_t1618 = false;
    FL_TRY(fl_cond(ctx, fl_t1617, &fl_t1618, error));
    fl_value fl_t1619;
    if (fl_t1618) {
      fl_t1619 = shag;
    } else {
      fl_value fl_t1620 = fl_nothing();
      FL_TRY(tls_client_mera_ubyvaet_6(ctx, shag, mesto, &fl_t1620, error));
      fl_t1619 = fl_t1620;
    }
    fl_value fl_t1621 = fl_nothing();
    FL_TRY(tls_client_bayty_do_mesta(ctx, tekst, fl_t1619, &fl_t1621, error));
    fl_value fl_t1622 = fl_nothing();
    FL_TRY(fl_b_dobavit(ctx, fl_t1616, fl_t1621, &fl_t1622, error));
    *result = fl_t1622;
    return FL_OK;
  }
}

/*
 * Функция flang «Байты до места».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param tekst — «текст»: строка
 * @param mesto — «место»: число
 * @return значение: список: число
 */
fl_status tls_client_bayty_do_mesta(fl_ctx *ctx, fl_value tekst, fl_value mesto,
                                    fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Байты до места", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status =
        tls_client_bayty_do_mesta_body(ctx, tekst, mesto, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

