/*
 * Функция flang «Секунд от эпохи».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param otmetka — «отметка»: «Отметка»
 * @return значение: число
 */
fl_status tls_client_sekund_ot_epohi(fl_ctx *ctx, fl_value otmetka,
                                     fl_value *result, fl_error *error) {
  if (fl_variant_is(otmetka, "Отметка")) {
    fl_value den = fl_nothing();
    FL_TRY(fl_variant_field(ctx, otmetka, "день", &den, error));
    fl_value chasy = fl_nothing();
    FL_TRY(fl_variant_field(ctx, otmetka, "часы", &chasy, error));
    fl_value smeschenie = fl_nothing();
    FL_TRY(fl_variant_field(ctx, otmetka, "смещение", &smeschenie, error));
    if (fl_variant_is(chasy, "Часы")) {
      fl_value chas = fl_nothing();
      FL_TRY(fl_variant_field(ctx, chasy, "час", &chas, error));
      fl_value minuta = fl_nothing();
      FL_TRY(fl_variant_field(ctx, chasy, "минута", &minuta, error));
      fl_value sekunda = fl_nothing();
      FL_TRY(fl_variant_field(ctx, chasy, "секунда", &sekunda, error));
      fl_value fl_t1695 = fl_nothing();
      FL_TRY(tls_client_dney_ot_epohi(ctx, den, &fl_t1695, error));
      if (fl_t1695.tag != FL_NUMBER)
        FL_TRY(fl_not_numbers(ctx, "mul", fl_t1695, fl_number(86400.0), error));
      if (chas.tag != FL_NUMBER)
        FL_TRY(fl_not_numbers(ctx, "mul", chas, fl_number(3600.0), error));
      if (minuta.tag != FL_NUMBER)
        FL_TRY(fl_not_numbers(ctx, "mul", minuta, fl_number(60.0), error));
      if (sekunda.tag != FL_NUMBER)
        FL_TRY(fl_not_numbers(ctx, "add", fl_number((((fl_t1695.as.number * 86400.0) + (chas.as.number * 3600.0)) + (minuta.as.number * 60.0))), sekunda, error));
      if (smeschenie.tag != FL_NUMBER)
        FL_TRY(fl_not_numbers(ctx, "mul", smeschenie, fl_number(60.0), error));
      *result = fl_number(((((fl_t1695.as.number * 86400.0) + (chas.as.number * 3600.0)) + (minuta.as.number * 60.0)) + sekunda.as.number) - (smeschenie.as.number * 60.0));
      return FL_OK;
    } else {
      return fl_match_fail(ctx, chasy, error);
    }
  } else {
    return fl_match_fail(ctx, otmetka, error);
  }
}

